window.RP_SESSION={"id":"S-9e60dd9a8f31","messages":[{"id":"RP-II-0135278","time":"2026-08-04T20:09:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가델랏 허그는 지금 훈련장에 있습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135279","time":"2026-08-04T20:09:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"보자… 멀쩡한 허수아비가…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135280","time":"2026-08-04T20:09:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"어우, 요즘 다들 훈련을 열심히 하나봅니다. 뭐는 찔려있고 뭐는 베어있네요.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135281","time":"2026-08-04T20:10:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"저 멀리서 그나마 멀쩡한거 하나를 끌고 와서는, 앞에 두고 그것으로부터 조금 멀어집니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135282","time":"2026-08-04T20:11:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가델랏 허그는 오른손에 가죽 장갑을 끼고, 바지에 덧댄 단추를 풀어 허리춤에 걸려있던 철퇴를 꺼내듭니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135283","time":"2026-08-04T20:12:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"지금부터는 허수아비를 이리 저리 패며, 손을 풀 생각입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135284","time":"2026-08-04T20:13:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"먼저, 말린 사슬을 조금 풀어 바닥에 늘어뜨리고는, 몸에서부터 회전을 실어 철퇴에 가속을 줍니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135285","time":"2026-08-04T20:13:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허수하비의 머리 오른쪽 부분을 철구로 강하게 가격해, 목이 꺾이도록 할 생각입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135286","time":"2026-08-04T20:14:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135287","time":"2026-08-04T20:14:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 격투 판정 :\n[5, 1, 2] + [1]\n성공수 : [ 1 ]","characters":[]},{"id":"RP-II-0135288","time":"2026-08-04T20:14:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"난이도는 2였으니 실패군요.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135289","time":"2026-08-04T20:15:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 마침내 철퇴를 허수아비의 머리를 향해, 회전하던 방향 그대로 오른쪽으로. 크게 궤도를 그리며 휘두르지만,","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135290","time":"2026-08-04T20:15:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"챙그랑-","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135291","time":"2026-08-04T20:16:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"사슬을 너무 푼 탓인지, 철구가 아닌 사슬이 녀석의 몸에 맞으며 철구는 왼편으로 말려 지나가버립니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135292","time":"2026-08-04T20:16:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"하지만","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135293","time":"2026-08-04T20:16:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"럭키 펀치! [2]\n(Lucky Punch!)\n한 전투에 한 번, 전사는 공격에 대한 재판정을 시도할 수 있습니다. 이는 플레이어의 선택에 따릅니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135294","time":"2026-08-04T20:16:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"난이도는 2","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135295","time":"2026-08-04T20:16:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135296","time":"2026-08-04T20:16:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 격투 판정 :\n[3, 6, 2] + [5]\n성공수 : [ 2 ]","characters":[]},{"id":"RP-II-0135297","time":"2026-08-04T20:17:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"사슬이 걸려 녀석의 몸을 넘어 왼편으로 지나가던 철구는","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135298","time":"2026-08-04T20:17:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 이걸 노렸지!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135299","time":"2026-08-04T20:18:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"사슬이 허수아비에 맞닿은 그 점을 기준으로, 다시금 회전이 걸리며 그대로 말려 허수아비의 왼쪽 어깨부분을 강하게 가격합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135300","time":"2026-08-04T20:18:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“휘유, 아직 실력 안죽었어.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135301","time":"2026-08-04T20:18:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135302","time":"2026-08-04T20:18:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 민첩 판정 :\n[5] + [2] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0135303","time":"2026-08-04T20:19:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 그리 말하며, 만족스러운 듯 사슬을 당겨 철퇴를 회수하려 했으나,\n이크!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135304","time":"2026-08-04T20:19:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"꾸웅—\n\n자신에게로 날아오는 철퇴에 무릎을 부딪혀버립니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135305","time":"2026-08-04T20:20:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄으으으으으으으으으읍…!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135306","time":"2026-08-04T20:20:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아오, 우아… 여이, 끄아흐…”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135307","time":"2026-08-04T20:21:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 연신 신음하며 자신의 무릎을 열심히 문지르다가, 조금 나아졌는지 사슬을 말아놓곤 철퇴를 다시 허리춤에 걸어놓습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135308","time":"2026-08-04T20:21:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아후… 오늘은 날이 아닌가…\n오늘은 한 잔만 마시고 들어가야겠네, 잠이 안깼나봐.“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135309","time":"2026-08-04T20:23:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 그리 말하며 훈련장을 나섭니다.\n걱정 마요 허그, 이정도 실수 쯤이야 자주 해왔던 거니까요.\n언젠가는 더 멋들어지게 철퇴를 다루는, 그런 사냥꾼이 되어있을겁니다. 힘내요!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135310","time":"2026-08-04T20:23:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 허그는 오늘도 어딜 다쳐서 기숙사로 돌아옵니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135311","time":"2026-08-04T20:23:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0135312","time":"2026-08-04T20:23:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]},{"id":"RP-II-0135313","time":"2026-08-04T20:34:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]}]};
